steps.script:
$ErrorActionPreference='Stop'
$o=@{state='pending'}
$t=Join-Path $env:TEMP ('TTEditorialGuard-'+[guid]::NewGuid().ToString('N')+'.ps1')
$listener='C:\TTiTTulares\TTiTTularesDedicatedListener.ps1'
$tmp=$listener+'.new'
try{
 $u='https://raw.githubusercontent.com/fabricelop/europapress-rss/4d5ebe90d94c09d49c4b0fd1be4979cd73c004ae/windows/Reparar-TT-Editorial-20261111.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $u -OutFile $t -TimeoutSec 35
 if(-not ([IO.File]::ReadAllText($t)).Contains('NEW_CHAT_NOT_BLANK state=')){throw 'GUARD_MARKER_MISSING'}
 & $t -NoDispatch *> $null
 if(-not $?){throw 'GUARD_INSTALL_FAILED'}
 if(-not (Get-Content 'C:\TTiTTulares\TT-Editorial-Guard.js' -Raw).Contains('NEW_CHAT_NOT_BLANK state=')){throw 'GUARD_NOT_UPDATED'}
 $u2='https://raw.githubusercontent.com/fabricelop/europapress-rss/5ffe65a9cb9a85ec7009f597c9f7f74dac120187/windows/TTiTTularesDedicatedListener.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $u2 -OutFile $tmp -TimeoutSec 35
 $src=Get-Content $tmp -Raw
 if(-not $src.Contains('$LaunchConfirmSeconds = 120')){throw 'LISTENER_MARKER_MISSING'}
 $tok=$null;$err=$null
 [Management.Automation.Language.Parser]::ParseFile($tmp,[ref]$tok,[ref]$err)|Out-Null
 if($err.Count){throw 'LISTENER_SYNTAX_INVALID'}
 Copy-Item $listener ($listener+'.before-120s-20261112.bak') -Force
 Move-Item $tmp $listener -Force
 $o.state='guard_and_listener_installed'
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
finally{Remove-Item $t,$tmp -Force -ErrorAction SilentlyContinue}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
